48	architecture Behavioral of MCP33131 is
49		signal conv_cnt : integer range 0 to CONVCYCLES-1;
50		signal div_cnt : integer range 0 to (CLK_DIV/2)-1;
51		signal bit_cnt : integer range 0 to 15;
52		signal sclk_phase : std_logic;
53		signal adc_data : std_logic_vector(15 downto 0);
54		type States is (Idle, Conversion, WAIT_tEN, Transmission, Done);
55		signal state : States;
56		signal ready_int : std_logic;
57		signal ready_delay : integer range 0 to 30;
58		signal min_int, max_int, data_int : signed(15 downto 0);
59	begin
60	
61		MIN <= std_logic_vector(min_int);
62		MAX <= std_logic_vector(max_int);
63		DATA <= std_logic_vector(data_int);
64		SCLK <= sclk_phase;
65	
66		process(SCLK, START)
67		begin
68			if(falling_edge(SCLK)) then
69				adc_data <= adc_data(14 downto 0) & SDO;
70			end if;
71		end process;
72	
73		process(CLK, RESET)
74		begin
75			if(rising_edge(CLK)) then
76				if(RESET = '1') then
77					state <= Idle;
78					READY <= '0';
79					ready_int <= '0';
80					CONVSTART <= '0';
81					sclk_phase <= '0';
82					CONVSTART <= '0';
83					conv_cnt <= 0;
84					div_cnt <= 0;
85					bit_cnt <= 0;
86					min_int <= to_signed(32767, 16);
87					max_int <= to_signed(-32768, 16);
88				else
89					if RESET_MINMAX = '1' then
90						min_int <= to_signed(32767, 16);
91						max_int <= to_signed(-32768, 16);
92					else
93						if data_int < min_int then
94							min_int <= data_int;
95						end if;
96						if data_int > max_int then
97							max_int <= data_int;
98						end if;
99					end if;
100					
101					READY <= '0';
102					if ready_int = '1' then
103						ready_delay <= 3;
104					else
105						if ready_delay > 0 then
106							ready_delay <= ready_delay - 1;
107						end if;
108						if ready_delay = 1 then
109							READY <= '1';
110							data_int <= signed(adc_data);
111						end if;
112					end if;
113					
114					case state is
115						when Idle =>
116							ready_int <= '0';
117							if START = '1' then
118								state <= Conversion;
119								conv_cnt <= 0;
120								CONVSTART <= '1';
121							end if;
122						when Conversion =>
123							ready_int <= '0';
124							if(conv_cnt < CONVCYCLES-1) then
125								conv_cnt <= conv_cnt + 1;
126							else
127								div_cnt <= 0;
128								CONVSTART <= '0';
129								state <= WAIT_tEN;
130							end if;
131						when WAIT_tEN =>
132							ready_int <= '0';
133							state <= Transmission;
134						when Transmission =>
135							ready_int <= '0';
136							if(div_cnt < (CLK_DIV/2)-1) then
137								div_cnt <= div_cnt + 1;
138							else
139								if(sclk_phase = '0') then
140									sclk_phase <= '1';
141								else
142									sclk_phase <= '0';
143									if bit_cnt = 15 then
144										state <= Done;
145										bit_cnt <= 0;
146									else
147										bit_cnt <= bit_cnt + 1;
148									end if;
149								end if;
150								div_cnt <= 0;
151							end if;
152						when Done =>
153							ready_int <= '1';
154							state <= Idle;
155					end case;
156				end if;
157			end if;
158		end process;
159	
