17	-- Additional Comments: 
18	--
19	----------------------------------------------------------------------------------
20	library IEEE;
21	use IEEE.STD_LOGIC_1164.ALL;
22	
23	-- Uncomment the following library declaration if using
24	-- arithmetic functions with Signed or Unsigned values
25	use IEEE.NUMERIC_STD.ALL;
26	
27	-- Uncomment the following library declaration if instantiating
28	-- any Xilinx primitives in this code.
29	--library UNISIM;
30	--use UNISIM.VComponents.all;
31	
32	entity Sampling is
33		 Generic(CLK_CYCLES_PRE_DONE : integer);
34	    Port ( CLK : in  STD_LOGIC;
35	           RESET : in  STD_LOGIC;
36				  ADC_PRESCALER : in STD_LOGIC_VECTOR(7 downto 0);
37				  PHASEINC : in STD_LOGIC_VECTOR(11 downto 0);
38	           PORT1 : in  STD_LOGIC_VECTOR (17 downto 0);
39	           PORT2 : in  STD_LOGIC_VECTOR (17 downto 0);
40	           REF : in  STD_LOGIC_VECTOR (17 downto 0);
41				  ADC_START : out STD_LOGIC;
42	           NEW_SAMPLE : in  STD_LOGIC;
43	           DONE : out  STD_LOGIC;
44	           PRE_DONE : out  STD_LOGIC;
45	           START : in  STD_LOGIC;
46	           SAMPLES : in  STD_LOGIC_VECTOR (12 downto 0);
47	           PORT1_I : out  STD_LOGIC_VECTOR (47 downto 0);
48	           PORT1_Q : out  STD_LOGIC_VECTOR (47 downto 0);
49	           PORT2_I : out  STD_LOGIC_VECTOR (47 downto 0);
50	           PORT2_Q : out  STD_LOGIC_VECTOR (47 downto 0);
51	           REF_I : out  STD_LOGIC_VECTOR (47 downto 0);
52	           REF_Q : out  STD_LOGIC_VECTOR (47 downto 0);
53				  ACTIVE : out STD_LOGIC);
54	end Sampling;
55	
56	architecture Behavioral of Sampling is
57	COMPONENT SinCos
58	  PORT (
59	    clk : IN STD_LOGIC;
60	    phase_in : IN STD_LOGIC_VECTOR(11 DOWNTO 0);
61	    cosine : OUT STD_LOGIC_VECTOR(15 DOWNTO 0);
62	    sine : OUT STD_LOGIC_VECTOR(15 DOWNTO 0)
63	  );
64	END COMPONENT;
65	COMPONENT DSP_SLICE
66		PORT (
67			clk : IN STD_LOGIC;
68			ce : IN STD_LOGIC;
69			sel : IN STD_LOGIC_VECTOR(0 DOWNTO 0);
70			a : IN STD_LOGIC_VECTOR(17 DOWNTO 0);
71			b : IN STD_LOGIC_VECTOR(17 DOWNTO 0);
72			c : IN STD_LOGIC_VECTOR(47 DOWNTO 0);
73			p : OUT STD_LOGIC_VECTOR(47 DOWNTO 0)
74		);
75	END COMPONENT;
76	COMPONENT window
77	PORT(
78		CLK : IN std_logic;
79		INDEX : IN std_logic_vector(6 downto 0);
80		WINDOW_TYPE : IN std_logic_vector(1 downto 0);          
81		VALUE : OUT std_logic_vector(15 downto 0)
82		);
83	END COMPONENT;
84	
85		signal p1_I : std_logic_vector(47 downto 0);
86		signal p1_Q : std_logic_vector(47 downto 0);
87		signal p2_I : std_logic_vector(47 downto 0);
88		signal p2_Q : std_logic_vector(47 downto 0);
89		signal r_I : std_logic_vector(47 downto 0);
90		signal r_Q : std_logic_vector(47 downto 0);
91		signal clk_cnt : integer range 0 to 255;
92		signal sample_cnt : integer range 0 to 131071;
93		signal samples_to_take : integer range 0 to 131071;
94		
95		signal phase : std_logic_vector(11 downto 0);
96		signal sine : std_logic_vector(15 downto 0);
97		signal cosine : std_logic_vector(15 downto 0);
98		
99		signal mult_a : std_logic_vector(17 downto 0);
100		signal mult_b : std_logic_vector(17 downto 0);
101		signal mult_c : std_logic_vector(47 downto 0);
102		signal mult_p : std_logic_vector(47 downto 0);
103		
104		signal mult_enable : std_logic;
105		signal mult_accumulate : std_logic_vector(0 downto 0);
106		
107		type States is (Idle, Sampling, P1Q, P2I, P2Q, RI, RQ, SaveP1Q, SaveP2I, SaveP2Q, SaveRI, SaveRQ, Ready);
108		signal state : States;
109	begin
110	-- Always fails for simulation, comment out
111	--	assert (phase_inc * CLK_FREQ / (4096*CLK_DIV) = IF_FREQ)
112	--		report "Phase increment not exact"
113	--		severity FAILURE;
114			
115		LookupTable : SinCos
116		PORT MAP (
117			clk => CLK,
118			phase_in => phase,
119			cosine => cosine,
120			sine => sine
121		);
122	
123		Mult : DSP_SLICE
124		PORT MAP (
125			clk => CLK,
126			ce => mult_enable,
127			sel => mult_accumulate,
128			a => mult_a,
129			b => mult_b,
130			c => mult_c,
131			p => mult_p
132		);
133		
134		-- sign extend b input of multiplier (sin/cos)
135		mult_b(17 downto 16) <= mult_b(15) & mult_b(15);
136		
137		process(CLK, RESET)
138		begin
139			if rising_edge(CLK) then
140				if RESET = '1' then
141					state <= Idle;
142					ADC_START <= '0';
143					DONE <= '0';
144					PRE_DONE <= '0';
145					ACTIVE <= '0';
146					clk_cnt <= 0;
147					sample_cnt <= 0;
148					phase <= (others => '0');
149					mult_enable <= '0';
150					mult_accumulate <= "0";
151				else
152					-- when not idle, generate pulses for ADCs
153					if state /= Idle then
154						if clk_cnt = unsigned(ADC_PRESCALER) - 1 then
155							if sample_cnt < samples_to_take then
156								ADC_START <= '1';
157							end if;
158							clk_cnt <= 0;
159						else
160							clk_cnt <= clk_cnt + 1;
161							ADC_START <= '0';
162						end if;
163					else
164						ADC_START <= '0';
165					end if;
166					-- handle state transitions
167					case state is
168						when Idle =>
169							sample_cnt <= 0;
170							DONE <= '0';
171							PRE_DONE <= '0';
172							ACTIVE <= '0';
173							clk_cnt <= 0;
174							phase <= (others => '0');
175							mult_enable <= '0';
176							mult_accumulate <= "0";
177							if START = '1' then
178								state <= Sampling;
179								samples_to_take <= to_integer(unsigned(SAMPLES & "0000"));
180							end if;
181						when Sampling =>
182							DONE <= '0';
183							PRE_DONE <= '0';
184							ACTIVE <= '1';
185							mult_enable <= '0';
186							if NEW_SAMPLE = '1' then
187								sample_cnt <= sample_cnt + 1;
188								mult_enable <= '1';
189								mult_a <= PORT1;
190								mult_b(15 downto 0) <= cosine;
191								mult_c <= p1_I;
192								state <= P1Q;
193							end if;
194						when P1Q =>
195							ACTIVE <= '1';
196							DONE <= '0';
197							PRE_DONE <= '0';
198							mult_enable <= '1';
199							mult_a <= PORT1;
200							mult_b(15 downto 0) <= sine;
201							mult_c <= p1_Q;
202							state <= P2I;
203						when P2I =>
204							ACTIVE <= '1';
205							DONE <= '0';
206							PRE_DONE <= '0';
207							mult_enable <= '1';
208							mult_a <= PORT2;
209							mult_b(15 downto 0) <= cosine;
210							mult_c <= p2_I;
211							state <= P2Q;
212						when P2Q =>
213							ACTIVE <= '1';
214							DONE <= '0';
215							PRE_DONE <= '0';
216							mult_enable <= '1';
217							mult_a <= PORT2;
218							mult_b(15 downto 0) <= sine;
219							mult_c <= p2_Q;
220							state <= RI;
221						when RI =>
222							ACTIVE <= '1';
223							DONE <= '0';
224							PRE_DONE <= '0';
225							mult_enable <= '1';
226							mult_a <= REF;
227							mult_b(15 downto 0) <= cosine;
228							mult_c <= r_I;
229							state <= RQ;						
230						when RQ =>
231							ACTIVE <= '1';
232							DONE <= '0';
233							PRE_DONE <= '0';
234							mult_enable <= '1';
235							mult_a <= REF;
236							mult_b(15 downto 0) <= sine;
237							mult_c <= r_Q;
238							-- first result is available
239							p1_I <= mult_p;
240							state <= SaveP1Q;
241						when SaveP1Q =>
242							ACTIVE <= '1';
243							DONE <= '0';
244							PRE_DONE <= '0';
245							mult_enable <= '1';
246							p1_Q <= mult_p;
247							state <= SaveP2I;
248						when SaveP2I =>
249							ACTIVE <= '1';
250							DONE <= '0';
251							PRE_DONE <= '0';
252							mult_enable <= '1';
253							p2_I <= mult_p;
254							state <= SaveP2Q;
255						when SaveP2Q =>
256							ACTIVE <= '1';
257							DONE <= '0';
258							PRE_DONE <= '0';
259							mult_enable <= '1';
260							p2_Q <= mult_p;
261							state <= SaveRI;
262						when SaveRI =>
263							ACTIVE <= '1';
264							DONE <= '0';
265							PRE_DONE <= '0';
266							mult_enable <= '1';
267							r_I <= mult_p;
268							state <= SaveRQ;
269						when SaveRQ =>
270							ACTIVE <= '1';
271							DONE <= '0';
272							PRE_DONE <= '0';
273							mult_enable <= '0';
274							r_Q <= mult_p;
275							-- from now on accumulate results
276							mult_accumulate <= "1";
277							phase <= std_logic_vector(unsigned(phase) + unsigned(PHASEINC));
278							if sample_cnt < samples_to_take then
279								state <= Sampling;
280							else
281								state <= Ready;
282							end if;
283						when Ready =>
284							ACTIVE <= '1';
285							DONE <= '1';
286							PRE_DONE <= '1';
287							mult_enable <= '0';
288							PORT1_I <= p1_I;
289							PORT1_Q <= p1_Q;
290							PORT2_I <= p2_I;
291							PORT2_Q <= p2_Q;
292							REF_I <= r_I;
293							REF_Q <= r_Q;
294							state <= Idle;
295					end case;
296				end if;
297			end if;
298		end process;
299	
300	end Behavioral;
301	
302

