    -- Component Declaration for the Unit Under Test (UUT)

    COMPONENT MCP33131
	 	 Generic(CLK_DIV : integer;
				CONVCYCLES : integer);
    PORT(
         CLK : IN  std_logic;
         RESET : IN  std_logic;
         START : IN  std_logic;
         READY : OUT  std_logic;
         DATA : OUT  std_logic_vector(15 downto 0);
			MIN : out STD_LOGIC_VECTOR (15 downto 0);
			MAX : out STD_LOGIC_VECTOR (15 downto 0);
